  ('9b2d0000-0000-4000-8000-000000000002', 'standard', 'Standard', 3, 90, 649900, 749700, 'Build the habit.', array['Everything in Basic', 'Unlimited group classes', 'Monthly body composition scan', 'Starter workout plan']::text[], false, 1),
