insert into public.trainers (id, slug, name, position, specialization, experience_years, bio, image_url, certifications, social, sort_order) values
  ('7a1c0f0e-0001-4c1a-9a01-000000000001', 'arjun-rao', 'Arjun Rao', 'Head Coach', 'Strength & Powerlifting', 12, 'National-level powerlifter turned coach. Arjun has guided 300+ members to their first bodyweight deadlift and beyond.', 'https://images.unsplash.com/photo-1567013127542-490d757e51fc?auto=format&fit=crop&w=900&q=75', array['NSCA-CSCS', 'USAPL Club Coach']::text[], '{"instagram":"https://instagram.com","youtube":"https://youtube.com"}'::jsonb, 0),
  ('7a1c0f0e-0002-4c1a-9a01-000000000002', 'meera-kapoor', 'Meera Kapoor', 'Performance Coach', 'HIIT & Fat Loss', 8, 'Former state-level sprinter who blends conditioning science with relentless energy. Meera runs our flagship HIIT programme.', 'https://images.unsplash.com/photo-1594381898411-846e7d193883?auto=format&fit=crop&w=900&q=75', array['ACE-CPT', 'Precision Nutrition L1']::text[], '{"instagram":"https://instagram.com"}'::jsonb, 1),
  ('7a1c0f0e-0003-4c1a-9a01-000000000003', 'kabir-singh', 'Kabir Singh', 'Senior Trainer', 'Hypertrophy & Physique', 9, 'Competitive physique athlete focused on intelligent volume and nutrition. Kabir builds programs that make progress visible.', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=900&q=75', array['ISSA-CPT', 'ISSN Sports Nutrition']::text[], '{"instagram":"https://instagram.com","x":"https://x.com"}'::jsonb, 2),
  ('7a1c0f0e-0004-4c1a-9a01-000000000004', 'zara-sheikh', 'Zara Sheikh', 'Boxing Coach', 'Boxing & Conditioning', 7, 'Amateur boxing champion bringing fight-camp conditioning to every member — technique first, then intensity.', 'https://images.unsplash.com/photo-1584735935682-2f2b69dff9d2?auto=format&fit=crop&w=900&q=75', array['AIBA Level 1', 'NASM-CPT']::text[], '{"instagram":"https://instagram.com"}'::jsonb, 3),
  ('7a1c0f0e-0005-4c1a-9a01-000000000005', 'vikram-menon', 'Vikram Menon', 'Functional Specialist', 'Functional & Sports Conditioning', 10, 'Strength coach to state cricket and football squads. Vikram specialises in speed, power and resilient athletes.', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=900&q=75', array['EXOS Performance', 'FMS Level 2']::text[], '{"instagram":"https://instagram.com","youtube":"https://youtube.com"}'::jsonb, 4),
  ('7a1c0f0e-0006-4c1a-9a01-000000000006', 'ananya-iyer', 'Ananya Iyer', 'Mobility & Yoga Lead', 'Mobility, Yoga & Recovery', 11, 'Physiotherapist and E-RYT 500 yoga teacher. Ananya keeps our members moving freely, recovering faster and training longer.', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?auto=format&fit=crop&w=900&q=75', array['BPT', 'E-RYT 500', 'FRC Mobility Specialist']::text[], '{"instagram":"https://instagram.com"}'::jsonb, 5)
