insert into public.testimonials (name, image_url, rating, review, transformation, member_since, sort_order) values
  ('Sneha Reddy', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=400&q=75', 5, 'The coaching here is on a different level. Every session has a purpose, every coach knows my numbers. I''ve never been this consistent.', '−9 kg in 14 weeks', '2023', 0),
  ('Karan Malhotra', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=400&q=75', 5, 'Premium facility, zero ego. The QR check-in, the app, the recovery zone — it feels like a members'' club built for people who actually train.', 'Squat 100 → 170 kg', '2022', 1),
  ('Aisha Khan', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=400&q=75', 5, 'Fight Camp with Zara changed how I train. I''m fitter at 38 than I was at 25 and I actually look forward to 6 AM.', 'Resting HR 78 → 58', '2024', 2),
  ('Nikhil Verma', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&q=75', 4, 'Signed up for the Premium plan and the custom diet + workout plan paid for itself in two months. Clean, organised and motivating.', '+6 kg lean mass', '2023', 3),
  ('Divya Menon', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=400&q=75', 5, 'Ananya''s mobility sessions fixed a back issue I had for years. The whole team genuinely cares about how you move.', 'Pain-free in 8 weeks', '2021', 4)
insert into public.blog_posts (slug, title, excerpt, category, cover_url, body, author, read_minutes, published_at, status) values
  ('progressive-overload-explained', 'Progressive Overload, Explained Without the Bro Science', 'The single principle behind every strength gain — and five practical ways to apply it this week.', 'Workout', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=1200&q=75', 'Your body adapts to exactly what you ask of it — and nothing more. Progressive overload is simply the practice of asking for a little more over time.
